head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jlddst60231";

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_rowCopy();
        scwin.init_conds();
        scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jlddst60231.onpageload' });
    }
};

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "c_when_32_txt", fn: function(){ return (String((dma_detail.get("hldStrtTm") ?? (() => { throw new Error("unresolved:" + "detail.hldStrtTm"); })())).substring(1, 2) === ':'); } }, { id: "c_when_33_txt", fn: function(){ return (String((dma_detail.get("hldStrtTm") ?? (() => { throw new Error("unresolved:" + "detail.hldStrtTm"); })())).substring(2, 3) === ':'); } }, { id: "c_otherwise_34", fn: function(){ return (!((String((dma_detail.get("hldStrtTm") ?? (() => { throw new Error("unresolved:" + "detail.hldStrtTm"); })())).substring(1, 2) === ':') || (String((dma_detail.get("hldStrtTm") ?? (() => { throw new Error("unresolved:" + "detail.hldStrtTm"); })())).substring(2, 3) === ':'))); } }, { id: "c_when_30", fn: function(){ return ((((dma_detail.get("hldStrtTm") ?? (() => { throw new Error("unresolved:" + "detail.hldStrtTm"); })())) && typeof ((dma_detail.get("hldStrtTm") ?? (() => { throw new Error("unresolved:" + "detail.hldStrtTm"); })())).getRowCount === 'function' ? ((dma_detail.get("hldStrtTm") ?? (() => { throw new Error("unresolved:" + "detail.hldStrtTm"); })())).getRowCount() : ((((dma_detail.get("hldStrtTm") ?? (() => { throw new Error("unresolved:" + "detail.hldStrtTm"); })())) == null) ? 0 : (((dma_detail.get("hldStrtTm") ?? (() => { throw new Error("unresolved:" + "detail.hldStrtTm"); })())).length || 0))) === 4); } }, { id: "c_when_35_txt", fn: function(){ return ((((dma_detail.get("hldStrtTm") ?? (() => { throw new Error("unresolved:" + "detail.hldStrtTm"); })())) && typeof ((dma_detail.get("hldStrtTm") ?? (() => { throw new Error("unresolved:" + "detail.hldStrtTm"); })())).getRowCount === 'function' ? ((dma_detail.get("hldStrtTm") ?? (() => { throw new Error("unresolved:" + "detail.hldStrtTm"); })())).getRowCount() : ((((dma_detail.get("hldStrtTm") ?? (() => { throw new Error("unresolved:" + "detail.hldStrtTm"); })())) == null) ? 0 : (((dma_detail.get("hldStrtTm") ?? (() => { throw new Error("unresolved:" + "detail.hldStrtTm"); })())).length || 0))) === 5); } }, { id: "c_otherwise_36", fn: function(){ return (!(((((dma_detail.get("hldStrtTm") ?? (() => { throw new Error("unresolved:" + "detail.hldStrtTm"); })())) && typeof ((dma_detail.get("hldStrtTm") ?? (() => { throw new Error("unresolved:" + "detail.hldStrtTm"); })())).getRowCount === 'function' ? ((dma_detail.get("hldStrtTm") ?? (() => { throw new Error("unresolved:" + "detail.hldStrtTm"); })())).getRowCount() : ((((dma_detail.get("hldStrtTm") ?? (() => { throw new Error("unresolved:" + "detail.hldStrtTm"); })())) == null) ? 0 : (((dma_detail.get("hldStrtTm") ?? (() => { throw new Error("unresolved:" + "detail.hldStrtTm"); })())).length || 0))) === 4) || ((((dma_detail.get("hldStrtTm") ?? (() => { throw new Error("unresolved:" + "detail.hldStrtTm"); })())) && typeof ((dma_detail.get("hldStrtTm") ?? (() => { throw new Error("unresolved:" + "detail.hldStrtTm"); })())).getRowCount === 'function' ? ((dma_detail.get("hldStrtTm") ?? (() => { throw new Error("unresolved:" + "detail.hldStrtTm"); })())).getRowCount() : ((((dma_detail.get("hldStrtTm") ?? (() => { throw new Error("unresolved:" + "detail.hldStrtTm"); })())) == null) ? 0 : (((dma_detail.get("hldStrtTm") ?? (() => { throw new Error("unresolved:" + "detail.hldStrtTm"); })())).length || 0))) === 5))); } }, { id: "c_when_28", fn: function(){ return (!(String(((dma_detail.get("hldStrtTm") ?? (() => { throw new Error("unresolved:" + "detail.hldStrtTm"); })())) == null ? '' : ((dma_detail.get("hldStrtTm") ?? (() => { throw new Error("unresolved:" + "detail.hldStrtTm"); })()))).length === 0)); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {void}
 * @hidden N
 */
scwin.init_rowCopy = function () {
    const rows = [{ childId: "__rb7", fn: function () { return String(String(dma_detail.get("hldStrtTm")).substring(0, 2)) + ":" + String(String(dma_detail.get("hldStrtTm")).substring(2, 4)); } }];
    rows.forEach(function (it) {
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { return; }  // as-is 가 서버 렌더로 그리던 반복 행 — 산출에 없는 칸은 건너뛴다
        let v;
        try { v = it.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); return; }
        if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); }
    });
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {void}
 * @hidden N
 */
scwin.init_pageBody = function () {
    try {
        $c.util.getComponent("dialog-loading").setStyle("display", "none");

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jlddst60231.onpageload' }); }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };
